from typing import Optional

from pyvkteamsclient.stentor.base.client import BaseStentorClient
from pyvkteamsclient.tracer import tracer


class CalendarMethods(BaseStentorClient):
    @tracer.start_as_current_span("stentor.calendar.calendar_setAutoStatus")
    def calendar_setAutoStatus(self, email: str, startTS, endTS):
        """
        Установка автостатуса 'on_meeting'
        """
        return self.post(
            path="api/v1/calendar/setAutoStatus",
            data={"email": email, "startTS": startTS, "endTS": endTS},
            headers={"Content-Type": "application/x-www-form-urlencoded"},
        )

    @tracer.start_as_current_span("stentor.calendar.calendar_createConference")
    def calendar_createConference(self, email: str, name: Optional[str] = None):
        """
        Создание конференции
        """
        try:
            response = self.post(
                path="api/v1/calendar/createConference",
                data={"email": email},
                headers={"Content-Type": "application/x-www-form-urlencoded"},
            )
        except Exception:
            response = self.post(
                path="api/v1/calendar/createConference",
                data={"email": email, "name": name},
                headers={"Content-Type": "application/x-www-form-urlencoded"},
            )

        return response
